{"version":3,"file":"js-yaml.js","sources":["../lib/common.js","../lib/exception.js","../lib/snippet.js","../lib/type.js","../lib/schema.js","../lib/type/str.js","../lib/type/seq.js","../lib/type/map.js","../lib/schema/failsafe.js","../lib/type/null.js","../lib/type/bool.js","../lib/type/int.js","../lib/type/float.js","../lib/schema/json.js","../lib/schema/core.js","../lib/type/timestamp.js","../lib/type/merge.js","../lib/type/binary.js","../lib/type/omap.js","../lib/type/pairs.js","../lib/type/set.js","../lib/schema/default.js","../lib/loader.js","../lib/dumper.js","../index.js","../lib/index_vite_proxy.tmp.mjs"],"sourcesContent":["'use strict'\n\nfunction isNothing (subject) {\n  return (typeof subject === 'undefined') || (subject === null)\n}\n\nfunction isObject (subject) {\n  return (typeof subject === 'object') && (subject !== null)\n}\n\nfunction toArray (sequence) {\n  if (Array.isArray(sequence)) return sequence\n  else if (isNothing(sequence)) return []\n\n  return [sequence]\n}\n\nfunction extend (target, source) {\n  if (source) {\n    const sourceKeys = Object.keys(source)\n\n    for (let index = 0, length = sourceKeys.length; index < length; index += 1) {\n      const key = sourceKeys[index]\n      target[key] = source[key]\n    }\n  }\n\n  return target\n}\n\nfunction repeat (string, count) {\n  let result = ''\n\n  for (let cycle = 0; cycle < count; cycle += 1) {\n    result += string\n  }\n\n  return result\n}\n\nfunction isNegativeZero (number) {\n  return (number === 0) && (Number.NEGATIVE_INFINITY === 1 / number)\n}\n\nmodule.exports.isNothing = isNothing\nmodule.exports.isObject = isObject\nmodule.exports.toArray = toArray\nmodule.exports.repeat = repeat\nmodule.exports.isNegativeZero = isNegativeZero\nmodule.exports.extend = extend\n","// YAML error class. http://stackoverflow.com/questions/8458984\n//\n'use strict'\n\nfunction formatError (exception, compact) {\n  let where = ''\n  const message = exception.reason || '(unknown reason)'\n\n  if (!exception.mark) return message\n\n  if (exception.mark.name) {\n    where += 'in \"' + exception.mark.name + '\" '\n  }\n\n  where += '(' + (exception.mark.line + 1) + ':' + (exception.mark.column + 1) + ')'\n\n  if (!compact && exception.mark.snippet) {\n    where += '\\n\\n' + exception.mark.snippet\n  }\n\n  return message + ' ' + where\n}\n\nfunction YAMLException (reason, mark) {\n  // Super constructor\n  Error.call(this)\n\n  this.name = 'YAMLException'\n  this.reason = reason\n  this.mark = mark\n  this.message = formatError(this, false)\n\n  // Include stack trace in error object\n  if (Error.captureStackTrace) {\n    // Chrome and NodeJS\n    Error.captureStackTrace(this, this.constructor)\n  } else {\n    // FF, IE 10+ and Safari 6+. Fallback for others\n    this.stack = (new Error()).stack || ''\n  }\n}\n\n// Inherit from Error\nYAMLException.prototype = Object.create(Error.prototype)\nYAMLException.prototype.constructor = YAMLException\n\nYAMLException.prototype.toString = function toString (compact) {\n  return this.name + ': ' + formatError(this, compact)\n}\n\nmodule.exports = YAMLException\n","'use strict'\n\nconst common = require('./common')\n\n// get snippet for a single line, respecting maxLength\nfunction getLine (buffer, lineStart, lineEnd, position, maxLineLength) {\n  let head = ''\n  let tail = ''\n  const maxHalfLength = Math.floor(maxLineLength / 2) - 1\n\n  if (position - lineStart > maxHalfLength) {\n    head = ' ... '\n    lineStart = position - maxHalfLength + head.length\n  }\n\n  if (lineEnd - position > maxHalfLength) {\n    tail = ' ...'\n    lineEnd = position + maxHalfLength - tail.length\n  }\n\n  return {\n    str: head + buffer.slice(lineStart, lineEnd).replace(/\\t/g, '→') + tail,\n    pos: position - lineStart + head.length // relative position\n  }\n}\n\nfunction padStart (string, max) {\n  return common.repeat(' ', max - string.length) + string\n}\n\nfunction makeSnippet (mark, options) {\n  options = Object.create(options || null)\n\n  if (!mark.buffer) return null\n\n  if (!options.maxLength) options.maxLength = 79\n  if (typeof options.indent !== 'number') options.indent = 1\n  if (typeof options.linesBefore !== 'number') options.linesBefore = 3\n  if (typeof options.linesAfter !== 'number') options.linesAfter = 2\n\n  const re = /\\r?\\n|\\r|\\0/g\n  const lineStarts = [0]\n  const lineEnds = []\n  let match\n  let foundLineNo = -1\n\n  while ((match = re.exec(mark.buffer))) {\n    lineEnds.push(match.index)\n    lineStarts.push(match.index + match[0].length)\n\n    if (mark.position <= match.index && foundLineNo < 0) {\n      foundLineNo = lineStarts.length - 2\n    }\n  }\n\n  if (foundLineNo < 0) foundLineNo = lineStarts.length - 1\n\n  let result = ''\n  const lineNoLength = Math.min(mark.line + options.linesAfter, lineEnds.length).toString().length\n  const maxLineLength = options.maxLength - (options.indent + lineNoLength + 3)\n\n  for (let i = 1; i <= options.linesBefore; i++) {\n    if (foundLineNo - i < 0) break\n    const line = getLine(\n      mark.buffer,\n      lineStarts[foundLineNo - i],\n      lineEnds[foundLineNo - i],\n      mark.position - (lineStarts[foundLineNo] - lineStarts[foundLineNo - i]),\n      maxLineLength\n    )\n    result = common.repeat(' ', options.indent) + padStart((mark.line - i + 1).toString(), lineNoLength) +\n      ' | ' + line.str + '\\n' + result\n  }\n\n  const line = getLine(mark.buffer, lineStarts[foundLineNo], lineEnds[foundLineNo], mark.position, maxLineLength)\n  result += common.repeat(' ', options.indent) + padStart((mark.line + 1).toString(), lineNoLength) +\n    ' | ' + line.str + '\\n'\n  result += common.repeat('-', options.indent + lineNoLength + 3 + line.pos) + '^' + '\\n'\n\n  for (let i = 1; i <= options.linesAfter; i++) {\n    if (foundLineNo + i >= lineEnds.length) break\n    const line = getLine(\n      mark.buffer,\n      lineStarts[foundLineNo + i],\n      lineEnds[foundLineNo + i],\n      mark.position - (lineStarts[foundLineNo] - lineStarts[foundLineNo + i]),\n      maxLineLength\n    )\n    result += common.repeat(' ', options.indent) + padStart((mark.line + i + 1).toString(), lineNoLength) +\n      ' | ' + line.str + '\\n'\n  }\n\n  return result.replace(/\\n$/, '')\n}\n\nmodule.exports = makeSnippet\n","'use strict'\n\nconst YAMLException = require('./exception')\n\nconst TYPE_CONSTRUCTOR_OPTIONS = [\n  'kind',\n  'multi',\n  'resolve',\n  'construct',\n  'instanceOf',\n  'predicate',\n  'represent',\n  'representName',\n  'defaultStyle',\n  'styleAliases'\n]\n\nconst YAML_NODE_KINDS = [\n  'scalar',\n  'sequence',\n  'mapping'\n]\n\nfunction compileStyleAliases (map) {\n  const result = {}\n\n  if (map !== null) {\n    Object.keys(map).forEach(function (style) {\n      map[style].forEach(function (alias) {\n        result[String(alias)] = style\n      })\n    })\n  }\n\n  return result\n}\n\nfunction Type (tag, options) {\n  options = options || {}\n\n  Object.keys(options).forEach(function (name) {\n    if (TYPE_CONSTRUCTOR_OPTIONS.indexOf(name) === -1) {\n      throw new YAMLException('Unknown option \"' + name + '\" is met in definition of \"' + tag + '\" YAML type.')\n    }\n  })\n\n  // TODO: Add tag format check.\n  this.options = options // keep original options in case user wants to extend this type later\n  this.tag = tag\n  this.kind = options['kind'] || null\n  this.resolve = options['resolve'] || function () { return true }\n  this.construct = options['construct'] || function (data) { return data }\n  this.instanceOf = options['instanceOf'] || null\n  this.predicate = options['predicate'] || null\n  this.represent = options['represent'] || null\n  this.representName = options['representName'] || null\n  this.defaultStyle = options['defaultStyle'] || null\n  this.multi = options['multi'] || false\n  this.styleAliases = compileStyleAliases(options['styleAliases'] || null)\n\n  if (YAML_NODE_KINDS.indexOf(this.kind) === -1) {\n    throw new YAMLException('Unknown kind \"' + this.kind + '\" is specified for \"' + tag + '\" YAML type.')\n  }\n}\n\nmodule.exports = Type\n","'use strict'\n\nconst YAMLException = require('./exception')\nconst Type = require('./type')\n\nfunction compileList (schema, name) {\n  const result = []\n\n  schema[name].forEach(function (currentType) {\n    let newIndex = result.length\n\n    result.forEach(function (previousType, previousIndex) {\n      if (previousType.tag === currentType.tag &&\n          previousType.kind === currentType.kind &&\n          previousType.multi === currentType.multi) {\n        newIndex = previousIndex\n      }\n    })\n\n    result[newIndex] = currentType\n  })\n\n  return result\n}\n\nfunction compileMap (/* lists... */) {\n  const result = {\n    scalar: {},\n    sequence: {},\n    mapping: {},\n    fallback: {},\n    multi: {\n      scalar: [],\n      sequence: [],\n      mapping: [],\n      fallback: []\n    }\n  }\n  function collectType (type) {\n    if (type.multi) {\n      result.multi[type.kind].push(type)\n      result.multi['fallback'].push(type)\n    } else {\n      result[type.kind][type.tag] = result['fallback'][type.tag] = type\n    }\n  }\n\n  for (let index = 0, length = arguments.length; index < length; index += 1) {\n    arguments[index].forEach(collectType)\n  }\n  return result\n}\n\nfunction Schema (definition) {\n  return this.extend(definition)\n}\n\nSchema.prototype.extend = function extend (definition) {\n  let implicit = []\n  let explicit = []\n\n  if (definition instanceof Type) {\n    // Schema.extend(type)\n    explicit.push(definition)\n  } else if (Array.isArray(definition)) {\n    // Schema.extend([ type1, type2, ... ])\n    explicit = explicit.concat(definition)\n  } else if (definition && (Array.isArray(definition.implicit) || Array.isArray(definition.explicit))) {\n    // Schema.extend({ explicit: [ type1, type2, ... ], implicit: [ type1, type2, ... ] })\n    if (definition.implicit) implicit = implicit.concat(definition.implicit)\n    if (definition.explicit) explicit = explicit.concat(definition.explicit)\n  } else {\n    throw new YAMLException('Schema.extend argument should be a Type, [ Type ], ' +\n      'or a schema definition ({ implicit: [...], explicit: [...] })')\n  }\n\n  implicit.forEach(function (type) {\n    if (!(type instanceof Type)) {\n      throw new YAMLException('Specified list of YAML types (or a single Type object) contains a non-Type object.')\n    }\n\n    if (type.loadKind && type.loadKind !== 'scalar') {\n      throw new YAMLException('There is a non-scalar type in the implicit list of a schema. Implicit resolving of such types is not supported.')\n    }\n\n    if (type.multi) {\n      throw new YAMLException('There is a multi type in the implicit list of a schema. Multi tags can only be listed as explicit.')\n    }\n  })\n\n  explicit.forEach(function (type) {\n    if (!(type instanceof Type)) {\n      throw new YAMLException('Specified list of YAML types (or a single Type object) contains a non-Type object.')\n    }\n  })\n\n  const result = Object.create(Schema.prototype)\n\n  result.implicit = (this.implicit || []).concat(implicit)\n  result.explicit = (this.explicit || []).concat(explicit)\n\n  result.compiledImplicit = compileList(result, 'implicit')\n  result.compiledExplicit = compileList(result, 'explicit')\n  result.compiledTypeMap = compileMap(result.compiledImplicit, result.compiledExplicit)\n\n  return result\n}\n\nmodule.exports = Schema\n","'use strict'\n\nconst Type = require('../type')\n\nmodule.exports = new Type('tag:yaml.org,2002:str', {\n  kind: 'scalar',\n  construct: function (data) { return data !== null ? data : '' }\n})\n","'use strict'\n\nconst Type = require('../type')\n\nmodule.exports = new Type('tag:yaml.org,2002:seq', {\n  kind: 'sequence',\n  construct: function (data) { return data !== null ? data : [] }\n})\n","'use strict'\n\nconst Type = require('../type')\n\nmodule.exports = new Type('tag:yaml.org,2002:map', {\n  kind: 'mapping',\n  construct: function (data) { return data !== null ? data : {} }\n})\n","// Standard YAML's Failsafe schema.\n// http://www.yaml.org/spec/1.2/spec.html#id2802346\n\n'use strict'\n\nconst Schema = require('../schema')\n\nmodule.exports = new Schema({\n  explicit: [\n    require('../type/str'),\n    require('../type/seq'),\n    require('../type/map')\n  ]\n})\n","'use strict'\n\nconst Type = require('../type')\n\nfunction resolveYamlNull (data) {\n  if (data === null) return true\n\n  const max = data.length\n\n  return (max === 1 && data === '~') ||\n         (max === 4 && (data === 'null' || data === 'Null' || data === 'NULL'))\n}\n\nfunction constructYamlNull () {\n  return null\n}\n\nfunction isNull (object) {\n  return object === null\n}\n\nmodule.exports = new Type('tag:yaml.org,2002:null', {\n  kind: 'scalar',\n  resolve: resolveYamlNull,\n  construct: constructYamlNull,\n  predicate: isNull,\n  represent: {\n    canonical: function () { return '~' },\n    lowercase: function () { return 'null' },\n    uppercase: function () { return 'NULL' },\n    camelcase: function () { return 'Null' },\n    empty: function () { return '' }\n  },\n  defaultStyle: 'lowercase'\n})\n","'use strict'\n\nconst Type = require('../type')\n\nfunction resolveYamlBoolean (data) {\n  if (data === null) return false\n\n  const max = data.length\n\n  return (max === 4 && (data === 'true' || data === 'True' || data === 'TRUE')) ||\n         (max === 5 && (data === 'false' || data === 'False' || data === 'FALSE'))\n}\n\nfunction constructYamlBoolean (data) {\n  return data === 'true' ||\n         data === 'True' ||\n         data === 'TRUE'\n}\n\nfunction isBoolean (object) {\n  return Object.prototype.toString.call(object) === '[object Boolean]'\n}\n\nmodule.exports = new Type('tag:yaml.org,2002:bool', {\n  kind: 'scalar',\n  resolve: resolveYamlBoolean,\n  construct: constructYamlBoolean,\n  predicate: isBoolean,\n  represent: {\n    lowercase: function (object) { return object ? 'true' : 'false' },\n    uppercase: function (object) { return object ? 'TRUE' : 'FALSE' },\n    camelcase: function (object) { return object ? 'True' : 'False' }\n  },\n  defaultStyle: 'lowercase'\n})\n","'use strict'\n\nconst common = require('../common')\nconst Type = require('../type')\n\nfunction isHexCode (c) {\n  return ((c >= 0x30/* 0 */) && (c <= 0x39/* 9 */)) ||\n         ((c >= 0x41/* A */) && (c <= 0x46/* F */)) ||\n         ((c >= 0x61/* a */) && (c <= 0x66/* f */))\n}\n\nfunction isOctCode (c) {\n  return ((c >= 0x30/* 0 */) && (c <= 0x37/* 7 */))\n}\n\nfunction isDecCode (c) {\n  return ((c >= 0x30/* 0 */) && (c <= 0x39/* 9 */))\n}\n\nfunction resolveYamlInteger (data) {\n  if (data === null) return false\n\n  const max = data.length\n  let index = 0\n  let hasDigits = false\n\n  if (!max) return false\n\n  let ch = data[index]\n\n  // sign\n  if (ch === '-' || ch === '+') {\n    ch = data[++index]\n  }\n\n  if (ch === '0') {\n    // 0\n    if (index + 1 === max) return true\n    ch = data[++index]\n\n    // base 2, base 8, base 16\n\n    if (ch === 'b') {\n      // base 2\n      index++\n\n      for (; index < max; index++) {\n        ch = data[index]\n        if (ch !== '0' && ch !== '1') return false\n        hasDigits = true\n      }\n      return hasDigits && isFinite(parseYamlInteger(data))\n    }\n\n    if (ch === 'x') {\n      // base 16\n      index++\n\n      for (; index < max; index++) {\n        if (!isHexCode(data.charCodeAt(index))) return false\n        hasDigits = true\n      }\n      return hasDigits && isFinite(parseYamlInteger(data))\n    }\n\n    if (ch === 'o') {\n      // base 8\n      index++\n\n      for (; index < max; index++) {\n        if (!isOctCode(data.charCodeAt(index))) return false\n        hasDigits = true\n      }\n      return hasDigits && isFinite(parseYamlInteger(data))\n    }\n  }\n\n  // base 10 (except 0)\n\n  for (; index < max; index++) {\n    if (!isDecCode(data.charCodeAt(index))) {\n      return false\n    }\n    hasDigits = true\n  }\n\n  if (!hasDigits) return false\n\n  return isFinite(parseYamlInteger(data))\n}\n\nfunction parseYamlInteger (data) {\n  let value = data\n  let sign = 1\n\n  let ch = value[0]\n\n  if (ch === '-' || ch === '+') {\n    if (ch === '-') sign = -1\n    value = value.slice(1)\n    ch = value[0]\n  }\n\n  if (value === '0') return 0\n\n  if (ch === '0') {\n    if (value[1] === 'b') return sign * parseInt(value.slice(2), 2)\n    if (value[1] === 'x') return sign * parseInt(value.slice(2), 16)\n    if (value[1] === 'o') return sign * parseInt(value.slice(2), 8)\n  }\n\n  return sign * parseInt(value, 10)\n}\n\nfunction constructYamlInteger (data) {\n  return parseYamlInteger(data)\n}\n\nfunction isInteger (object) {\n  return (Object.prototype.toString.call(object)) === '[object Number]' &&\n         (object % 1 === 0 && !common.isNegativeZero(object))\n}\n\nmodule.exports = new Type('tag:yaml.org,2002:int', {\n  kind: 'scalar',\n  resolve: resolveYamlInteger,\n  construct: constructYamlInteger,\n  predicate: isInteger,\n  represent: {\n    binary: function (obj) { return obj >= 0 ? '0b' + obj.toString(2) : '-0b' + obj.toString(2).slice(1) },\n    octal: function (obj) { return obj >= 0 ? '0o' + obj.toString(8) : '-0o' + obj.toString(8).slice(1) },\n    decimal: function (obj) { return obj.toString(10) },\n    hexadecimal: function (obj) { return obj >= 0 ? '0x' + obj.toString(16).toUpperCase() : '-0x' + obj.toString(16).toUpperCase().slice(1) }\n  },\n  defaultStyle: 'decimal',\n  styleAliases: {\n    binary: [2, 'bin'],\n    octal: [8, 'oct'],\n    decimal: [10, 'dec'],\n    hexadecimal: [16, 'hex']\n  }\n})\n","'use strict'\n\nconst common = require('../common')\nconst Type = require('../type')\n\nconst YAML_FLOAT_PATTERN = new RegExp(\n  // 2.5e4, 2.5 and integers\n  '^(?:[-+]?(?:[0-9]+)(?:\\\\.[0-9]*)?(?:[eE][-+]?[0-9]+)?' +\n  // .2e4, .2\n  // special case, seems not from spec\n  '|\\\\.[0-9]+(?:[eE][-+]?[0-9]+)?' +\n  // .inf\n  '|[-+]?\\\\.(?:inf|Inf|INF)' +\n  // .nan\n  '|\\\\.(?:nan|NaN|NAN))$')\n\nconst YAML_FLOAT_SPECIAL_PATTERN = new RegExp(\n  '^(?:' +\n  // .inf\n  '[-+]?\\\\.(?:inf|Inf|INF)' +\n  // .nan\n  '|\\\\.(?:nan|NaN|NAN))$')\n\nfunction resolveYamlFloat (data) {\n  if (data === null) return false\n\n  if (!YAML_FLOAT_PATTERN.test(data)) {\n    return false\n  }\n\n  if (isFinite(parseFloat(data, 10))) {\n    return true\n  }\n\n  return YAML_FLOAT_SPECIAL_PATTERN.test(data)\n}\n\nfunction constructYamlFloat (data) {\n  let value = data.toLowerCase()\n  const sign = value[0] === '-' ? -1 : 1\n\n  if ('+-'.indexOf(value[0]) >= 0) {\n    value = value.slice(1)\n  }\n\n  if (value === '.inf') {\n    return (sign === 1) ? Number.POSITIVE_INFINITY : Number.NEGATIVE_INFINITY\n  } else if (value === '.nan') {\n    return NaN\n  }\n  return sign * parseFloat(value, 10)\n}\n\nconst SCIENTIFIC_WITHOUT_DOT = /^[-+]?[0-9]+e/\n\nfunction representYamlFloat (object, style) {\n  if (isNaN(object)) {\n    switch (style) {\n      case 'lowercase': return '.nan'\n      case 'uppercase': return '.NAN'\n      case 'camelcase': return '.NaN'\n    }\n  } else if (Number.POSITIVE_INFINITY === object) {\n    switch (style) {\n      case 'lowercase': return '.inf'\n      case 'uppercase': return '.INF'\n      case 'camelcase': return '.Inf'\n    }\n  } else if (Number.NEGATIVE_INFINITY === object) {\n    switch (style) {\n      case 'lowercase': return '-.inf'\n      case 'uppercase': return '-.INF'\n      case 'camelcase': return '-.Inf'\n    }\n  } else if (common.isNegativeZero(object)) {\n    return '-0.0'\n  }\n\n  const res = object.toString(10)\n\n  // JS stringifier can build scientific format without dots: 5e-100,\n  // while YAML requres dot: 5.e-100. Fix it with simple hack\n\n  return SCIENTIFIC_WITHOUT_DOT.test(res) ? res.replace('e', '.e') : res\n}\n\nfunction isFloat (object) {\n  return (Object.prototype.toString.call(object) === '[object Number]') &&\n         (object % 1 !== 0 || common.isNegativeZero(object))\n}\n\nmodule.exports = new Type('tag:yaml.org,2002:float', {\n  kind: 'scalar',\n  resolve: resolveYamlFloat,\n  construct: constructYamlFloat,\n  predicate: isFloat,\n  represent: representYamlFloat,\n  defaultStyle: 'lowercase'\n})\n","// Standard YAML's JSON schema.\n// http://www.yaml.org/spec/1.2/spec.html#id2803231\n//\n// NOTE: JS-YAML does not support schema-specific tag resolution restrictions.\n// So, this schema is not such strict as defined in the YAML specification.\n// It allows numbers in binary notaion, use `Null` and `NULL` as `null`, etc.\n\n'use strict'\n\nmodule.exports = require('./failsafe').extend({\n  implicit: [\n    require('../type/null'),\n    require('../type/bool'),\n    require('../type/int'),\n    require('../type/float')\n  ]\n})\n","// Standard YAML's Core schema.\n// http://www.yaml.org/spec/1.2/spec.html#id2804923\n//\n// NOTE: JS-YAML does not support schema-specific tag resolution restrictions.\n// So, Core schema has no distinctions from JSON schema is JS-YAML.\n\n'use strict'\n\nmodule.exports = require('./json')\n","'use strict'\n\nconst Type = require('../type')\n\nconst YAML_DATE_REGEXP = new RegExp(\n  '^([0-9][0-9][0-9][0-9])' + // [1] year\n  '-([0-9][0-9])' + // [2] month\n  '-([0-9][0-9])$')                   // [3] day\n\nconst YAML_TIMESTAMP_REGEXP = new RegExp(\n  '^([0-9][0-9][0-9][0-9])' + // [1] year\n  '-([0-9][0-9]?)' + // [2] month\n  '-([0-9][0-9]?)' + // [3] day\n  '(?:[Tt]|[ \\\\t]+)' + // ...\n  '([0-9][0-9]?)' + // [4] hour\n  ':([0-9][0-9])' + // [5] minute\n  ':([0-9][0-9])' + // [6] second\n  '(?:\\\\.([0-9]*))?' + // [7] fraction\n  '(?:[ \\\\t]*(Z|([-+])([0-9][0-9]?)' + // [8] tz [9] tz_sign [10] tzHour\n  '(?::([0-9][0-9]))?))?$')           // [11] tzMinute\n\nfunction resolveYamlTimestamp (data) {\n  if (data === null) return false\n  if (YAML_DATE_REGEXP.exec(data) !== null) return true\n  if (YAML_TIMESTAMP_REGEXP.exec(data) !== null) return true\n  return false\n}\n\